use solana_program::{account_info::AccountInfo, entrypoint, entrypoint::ProgramResult, msg, pubkey::Pubkey};

const TIER_THRESHOLDS: [u64; 3] = [0, 1_000_000, 10_000_000]; // in lamports
const TIER_FEES: [u8; 3] = [15, 10, 5]; // percentage fee

entrypoint!(process_instruction);
fn process_instruction(_program_id: &Pubkey, accounts: &[AccountInfo], instruction_data: &[u8]) -> ProgramResult {
    let revenue_account = &accounts[0];
    let revenue = revenue_account.try_borrow_data()?.as_slice()[..8].try_into().unwrap();
    let revenue = u64::from_le_bytes(revenue);

