Here’s a minimal XChaCha20‑Poly1305 wrapper you can drop into your helper crate: 

```rust
use aes_gcm_siv::Aes256GcmSiv; // or use `chacha20poly1305` crate
use chacha20poly1305::{XChaCha20Poly1305, Key, XNonce};
use rand::RngCore;

pub struct Cipher {
    cipher: XChaCha20Poly1305,
}

impl Cipher {
    pub fn new(secret: &[u8; 32]) -> Self {
        Self { cipher: XChaCha20Poly1305::new(&Key::from_slice(secret)) }
    }

    pub fn encrypt(&self, plaintext: &[u8]) -> Vec<u8> {
        let mut nonce = [0u8; 24];
        rand::thread_rng().fill_bytes(&mut nonce);
        let tag = self.cipher.encrypt(&XNonce::from_slice(&nonce), plaintext)
            .expect("encryption failed");
        [nonce.to_vec(), tag.to_vec()].concat()
    }

    pub fn decrypt(&self, data: &[u8]) -> Result<Vec<u8>, chacha20poly1305::Error> {
        let (nonce, tag) = data.split_at(24);
        self.cipher.decrypt(&XNonce::from_slice(nonce), tag)
    }
}
```

Just tweak the key‑size or swap in `Aes256GcmSiv` if you need deterministic encryption. Feel free to bundle it as a `no‑std` crate if you’re targeting embedded agents. Happy hacking!

